// A workshop's reply to the autogenerated email (ADR-033). Workshops never sign up; a reply with the estimate or invoice attached is filed on the
// job card, flagged for staff, who type the figures in. Nothing is read out of the message, and nothing is filed for a closed or unknown request.
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { testDriver, tenantMigrations, stripExt } from "./helpers";
import { provisionTenant } from "@/lib/db/provision";
import { withLinkContext, withPlatform, withTenant } from "@/lib/db/tenant";
import { ForbiddenError, type Membership } from "@/lib/auth/can";
import * as master from "@/lib/master/service";
import * as jc from "@/lib/jobcards/service";
import * as vf from "@/lib/vendorflow/service";
import { enterForWorkshop } from "@/lib/vendorflow/entry";
import { submitViaQuoteLink } from "@/lib/vendorflow/link";
import { bareAddress, codeFromAddresses, inboundConfigured, MAX_REPLIES_PER_REQUEST, newReplyCode, processInboundEmail, replyAddress, replyCodeHash, replyText, type InboundDeps } from "@/lib/vendorflow/inbound";
import { signWebhook, verifyWebhook } from "@/lib/email/webhook";
import { buildWorkshopMail } from "@/lib/email/workshop";
import { POST as inboundRoute } from "@/app/api/inbound/email/route";
import type { NextRequest } from "next/server";

const U = (n: number) => `00000000-0000-0000-0000-00000000${String(n).padStart(4, "0")}`;
let d: Awaited<ReturnType<typeof testDriver>>;
let t: { tenantId: string; schema: string };
const mem = (role: string, n: number, vehicleScope: "all" | "own" = "all"): Membership => ({ ...t, userId: U(n), role, vehicleScope });
const owner = () => mem("tenant_admin", 1);
const driver = () => mem("requester", 11, "own");
const mgr = () => mem("fleet_manager", 12);
const mgr2 = () => mem("fleet_manager", 13);
const raw = <T,>(m: Membership, fn: (q: import("@/lib/db/types").Queryable) => Promise<T>) => withTenant(d, m, fn);
let veh: string, reason: string, vA: string;

const env0 = { ...process.env };
beforeAll(async () => {
  process.env.INBOUND_REPLY_DOMAIN = "reply.example.test";
  process.env.RESEND_API_KEY = "re_test_key";
  process.env.RESEND_WEBHOOK_SECRET = "whsec_" + Buffer.from("a-test-secret-of-some-length-1234").toString("base64");
  d = await testDriver();
  t = await provisionTenant(d, { name: "Foxtrot Textiles", slug: "foxtrot", ownerUserId: U(1), ownerName: "Owner" }, tenantMigrations(), { transform: stripExt });
  for (const [n, name] of [[11, "Driver One"], [12, "Manager One"], [13, "Manager Two"]] as const) {
    const e = await master.saveEmployee(d, owner(), { full_name: name, employee_no: `E-${n}` });
    await raw(owner(), (q) => q.query("update employees set user_id = $1 where id = $2", [U(n), e.id]));
  }
  vA = (await master.saveVendor(d, owner(), { name: "Quick Fix Motors", categories: ["brakes"] })).id;
  await raw(owner(), (q) => q.query("update vendors set phone = '0300 1234567', email = 'office@quickfix.example' where id = $1", [vA]));
  await withPlatform(d, async (q) => {
    for (const [n, role] of [[11, "requester"], [12, "fleet_manager"], [13, "fleet_manager"]] as const)
      await q.query("insert into public.tenant_memberships(user_id, tenant_id, role) values ($1, $2, $3)", [U(n), t.tenantId, role]);
  });
  const emp11 = await raw(owner(), async (q) => (await q.query<{ id: string }>("select id from employees where user_id = $1", [U(11)])).rows[0].id);
  veh = (await master.addVehicle(d, owner(), { registration_no: "RPL-245", employee_id: emp11, holding_since: "2026-01-01" })).id;
  reason = (await raw(owner(), async (q) => (await q.query<{ id: string }>("select id from reason_codes where code = 'WEAR_BRAKES'")).rows[0])).id;
});
afterAll(() => { process.env = { ...env0 }; });
beforeEach(async () => { await withPlatform(d, (q) => q.query("update public.quotation_links set revoked_at = now() where revoked_at is null")); });

const PDF = new TextEncoder().encode("%PDF-1.4\n1 0 obj\n<<>>\nendobj\ntrailer\n%%EOF");
const EXE = new TextEncoder().encode("MZ\x90\x00 not a photo or a pdf");
const stored: { path: string; mime: string }[] = [];
let mailCount = 0;
const deps = (over: Partial<InboundDeps> = {}, from = "Quick Fix <office@quickfix.example>"): InboundDeps => ({
  fetchEmail: async (id) => ({ id, from, subject: "Re: estimate", text: "Please find our estimate attached.\n\nOn Tue, 27 Oct 2026, Fleet wrote:\n> long quoted history", html: null, messageId: `<msg-${id}@quickfix.example>` }),
  fetchFiles: async () => [{ filename: "estimate.pdf", size: PDF.length, downloadUrl: "https://files.example.test/a" }, { filename: "setup.exe", size: EXE.length, downloadUrl: "https://files.example.test/b" }],
  download: async (url) => (url.endsWith("/a") ? PDF : EXE),
  store: async (path, _b, mime) => { stored.push({ path, mime }); },
  newId: () => `id${++mailCount}`,
  ...over,
});

async function assigned(): Promise<string> {
  const { id } = await jc.createJobCard(d, driver(), { vehicle_id: veh, reason_code_id: reason, cause_text: "Front brake pads worn to the metal", lines: [] }, true);
  await jc.transitionJobCard(d, mgr2(), id, "approved");
  await jc.transitionJobCard(d, mgr(), id, "vendor_assigned", { vendorId: vA });
  return id;
}
const statusOf = (id: string) => raw(owner(), async (q) => (await q.query<{ status: string }>("select status from job_cards where id = $1", [id])).rows[0].status);
const emailsOf = (job: string) => raw(owner(), async (q) => (await q.query<Record<string, unknown>>("select * from workshop_emails where job_card_id = $1 order by received_at", [job])).rows);
const repliesUsed = (code: string) => withPlatform(d, async (q) => (await q.query<{ n: number }>("select replies_used n from public.quotation_links where reply_code_hash = $1", [replyCodeHash(code)])).rows[0]?.n);

describe("the reply address", () => {
  it("is made from a random code on our reply domain, and read back from any form an address takes", () => {
    const c = newReplyCode();
    expect(c).toMatch(/^[0-9a-f]{24}$/);
    expect(newReplyCode()).not.toBe(c);
    expect(replyAddress(c)).toBe(`w-${c}@reply.example.test`);
    expect(codeFromAddresses([replyAddress(c)])).toBe(c);
    expect(codeFromAddresses([`Fleet OTG <${replyAddress(c).toUpperCase()}>`])).toBe(c);
    expect(codeFromAddresses(["someone@else.test", replyAddress(c)])).toBe(c);
  });
  it("refuses another domain, a short or odd code, and anything that is not one of ours", () => {
    const c = newReplyCode();
    for (const a of [`w-${c}@evil.test`, `w-${c.slice(1)}@reply.example.test`, `x-${c}@reply.example.test`, `w-${c}@reply.example.test.evil.test`, `w-${"g".repeat(24)}@reply.example.test`, "", "a@b.c"])
      expect(codeFromAddresses([a])).toBeNull();
  });
  it("is only advertised when receiving is fully set up", () => {
    expect(inboundConfigured()).toBe(true);
    const k = process.env.RESEND_WEBHOOK_SECRET; delete process.env.RESEND_WEBHOOK_SECRET;
    expect(inboundConfigured()).toBe(false);
    process.env.RESEND_WEBHOOK_SECRET = k;
  });
  it("goes on the email as its reply-to, and the email says a reply is welcome only then", () => {
    const c = newReplyCode();
    const withReply = buildWorkshopMail({ to: "w@x.test", kind: "invoice", vendorName: "Quick Fix", orgName: "Foxtrot", jobNo: "JC-1", url: "https://x.test/q/abc", siteUrl: "https://x.test", replyTo: replyAddress(c) });
    expect(withReply.replyTo).toBe(replyAddress(c));
    expect(withReply.text).toMatch(/reply to this email/i);
    const without = buildWorkshopMail({ to: "w@x.test", kind: "invoice", vendorName: "Quick Fix", orgName: "Foxtrot", jobNo: "JC-1", url: "https://x.test/q/abc", siteUrl: "https://x.test" });
    expect(without.replyTo).toBeUndefined();
    expect(without.text).not.toMatch(/reply to this email/i);
  });
});

describe("reading a reply", () => {
  it("keeps what the sender wrote, drops quoted history, strips markup, and bounds the length", () => {
    expect(replyText("Estimate attached.\n\nOn Tue, 27 Oct 2026, Fleet wrote:\n> old", null)).toBe("Estimate attached.");
    expect(replyText(null, "<p>Hello <b>there</b></p><style>x{}</style><p>Total 3,800</p>")).toMatch(/Hello there\s+Total 3,800/);
    expect(replyText("x".repeat(9000), null).length).toBe(4000);
    expect(bareAddress("Quick Fix <Office@QuickFix.example>")).toBe("office@quickfix.example");
  });
  it("accepts a signed call from Resend (svix headers, whsec secret) and refuses the rest", () => {
    const secret = process.env.RESEND_WEBHOOK_SECRET!;
    const body = JSON.stringify({ type: "email.received", data: { email_id: "abc12345" } });
    const ts = String(Math.floor(Date.now() / 1000));
    const sig = `v1,${signWebhook(secret, "msg_1", ts, body)}`;
    expect(verifyWebhook(secret, body, { id: "msg_1", timestamp: ts, signature: sig })).toBe(true);
    expect(verifyWebhook(secret, body + " ", { id: "msg_1", timestamp: ts, signature: sig })).toBe(false);
    expect(verifyWebhook(secret, body, { id: "msg_1", timestamp: String(Number(ts) - 3600), signature: sig })).toBe(false);
  });
});

describe("filing a reply on the job card", () => {
  it("saves the message and its photos and PDFs on the job card, flags it for staff, and tells the people who decide", async () => {
    const job = await assigned();
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });
    expect(l.replyCode).toMatch(/^[0-9a-f]{24}$/);
    const before = stored.length;
    const out = await processInboundEmail(d, deps(), { emailId: "email1", addresses: [`Fleet <${replyAddress(l.replyCode!)}>`] });
    expect(out).toMatchObject({ status: "filed", saved: 1, skipped: 1 });                 // the PDF is kept, the program file is not
    expect(stored.slice(before)).toHaveLength(1);
    expect(stored[stored.length - 1].mime).toBe("application/pdf");
    expect(stored[stored.length - 1].path.startsWith(`${t.schema}/job_card/${job}/`)).toBe(true);
    const [e] = await emailsOf(job);
    expect(e).toMatchObject({ kind: "quotation", status: "new", sender_matches: true, file_count: 1, from_address: "office@quickfix.example" });
    expect(String(e.body_text)).toContain("Please find our estimate attached.");
    expect(String(e.body_text)).not.toContain("long quoted history");
    expect(String(e.body_text)).toMatch(/1 attachment was not saved/);
    const files = await raw(owner(), async (q) => (await q.query<{ n: string }>("select count(*)::text n from attachments where entity_type = 'job_card' and entity_id = $1", [job])).rows[0].n);
    expect(files).toBe("1");
    const note = await raw(owner(), async (q) => (await q.query<{ n: string }>("select count(*)::text n from notifications where kind = 'workshop.email' and payload->>'job_card_id' = $1", [job])).rows[0].n);
    expect(Number(note)).toBeGreaterThan(0);
    expect(await statusOf(job)).toBe("vendor_assigned");                                   // nothing is read out of the message: the card has not moved
    expect(await repliesUsed(l.replyCode!)).toBe(1);
    expect((await vf.listWorkshopEmails(d, mgr(), job))).toHaveLength(1);
  });
  it("marks a reply from a different address, so staff check before they trust it", async () => {
    const job = await assigned();
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });
    await processInboundEmail(d, deps({}, "Someone Else <stranger@else.test>"), { emailId: "email2", addresses: [replyAddress(l.replyCode!)] });
    expect((await emailsOf(job))[0]).toMatchObject({ sender_matches: false, from_address: "stranger@else.test" });
  });
  it("files a repeated delivery of the same message once", async () => {
    const job = await assigned();
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });
    const a = await processInboundEmail(d, deps(), { emailId: "email3", addresses: [replyAddress(l.replyCode!)] });
    const b = await processInboundEmail(d, deps(), { emailId: "email3", addresses: [replyAddress(l.replyCode!)] });
    expect(a.status).toBe("filed");
    expect(b).toEqual({ status: "ignored" });
    expect(await emailsOf(job)).toHaveLength(1);
    expect(await raw(owner(), async (q) => (await q.query<{ n: string }>("select count(*)::text n from attachments where entity_id = $1", [job])).rows[0].n)).toBe("1");
  });
  it("takes a few replies at most for one request", async () => {
    const job = await assigned();
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });
    for (let i = 0; i < MAX_REPLIES_PER_REQUEST; i++) expect((await processInboundEmail(d, deps({ fetchFiles: async () => [] }), { emailId: `many${i}`, addresses: [replyAddress(l.replyCode!)] })).status).toBe("filed");
    expect((await processInboundEmail(d, deps({ fetchFiles: async () => [] }), { emailId: "many-over", addresses: [replyAddress(l.replyCode!)] })).status).toBe("ignored");
    expect(await emailsOf(job)).toHaveLength(MAX_REPLIES_PER_REQUEST);
  });
  it("files nothing for an unknown address, a revoked request or a job that has moved on", async () => {
    const job = await assigned();
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });
    expect((await processInboundEmail(d, deps(), { emailId: "x1", addresses: [replyAddress(newReplyCode())] })).status).toBe("ignored");
    expect((await processInboundEmail(d, deps(), { emailId: "x2", addresses: ["someone@else.test"] })).status).toBe("ignored");
    const newer = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });        // a newer email replaces the older one
    expect((await processInboundEmail(d, deps(), { emailId: "x3", addresses: [replyAddress(l.replyCode!)] })).status).toBe("ignored");
    // the workshop sends its estimate through the link, and the estimate is approved: a reply to the email no longer lands anywhere
    expect(await submitViaQuoteLink(d, newer.token, { lines: [{ kind: "part", description: "Pads", qty: "1", unit_cost: "100" }] })).toEqual({ ok: true });
    await vf.decideQuotation(d, mgr(), (await vf.getJobFlow(d, mgr(), job)).quotations[0].id, "approve");
    expect((await processInboundEmail(d, deps(), { emailId: "x4", addresses: [replyAddress(newer.replyCode!)] })).status).toBe("ignored");
    expect(await emailsOf(job)).toHaveLength(0);
  });
  it("the inbound role can call its functions and read nothing", async () => {
    await expect(withLinkContext(d, t.schema, (q) => q.query("select * from workshop_emails"), "inbound_mail")).rejects.toThrow(/permission denied/);
    await expect(withLinkContext(d, t.schema, (q) => q.query("select * from job_cards"), "inbound_mail")).rejects.toThrow(/permission denied/);
    await expect(withLinkContext(d, t.schema, (q) => q.query("select * from attachments"), "inbound_mail")).rejects.toThrow(/permission denied/);
    await expect(withLinkContext(d, t.schema, (q) => q.query("select submit_quotation_via_link(gen_random_uuid(), gen_random_uuid(), '{}'::jsonb, 'x')"), "inbound_mail")).rejects.toThrow(/permission denied/);
    await expect(withLinkContext(d, t.schema, (q) => q.query("select add_workshop_email_file(gen_random_uuid(), 'tenant_other/x/y.pdf', 'y.pdf', 'application/pdf')"), "inbound_mail")).rejects.toThrow(/email not found|outside this workspace/);
  });
});

describe("staff type the figures in", () => {
  const estimate = { lines: [{ kind: "part", description: "Brake pads", qty: "2", unit_cost: "1500" }], details: "From the emailed PDF" };
  it("moves the job card exactly as the workshop's own form would, names the person in the history, and closes the email", async () => {
    const job = await assigned();
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation", { withReply: true });
    await processInboundEmail(d, deps(), { emailId: "staff1", addresses: [replyAddress(l.replyCode!)] });
    const [e] = await vf.listWorkshopEmails(d, mgr(), job);
    await enterForWorkshop(d, mgr(), job, "quotation", estimate, e.id);
    expect(await statusOf(job)).toBe("quotation_received");
    const flow = await vf.getJobFlow(d, mgr(), job);
    expect(Number(flow.quotations[0].amount)).toBe(3000);
    const ev = await raw(owner(), async (q) => (await q.query<{ comment: string | null }>("select comment from job_card_events where job_card_id = $1 and to_status = 'quotation_received'", [job])).rows[0]);
    expect(ev.comment).toBe("Estimate typed in by Manager One from the workshop's email");
    expect((await vf.listWorkshopEmails(d, mgr(), job))[0].status).toBe("entered");
  });
  it("works for an invoice too, with the work recorded as done", async () => {
    const job = await assigned();
    const q = await vf.createWorkshopLink(d, mgr(), job, "quotation");
    expect(await submitViaQuoteLink(d, q.token, estimate)).toEqual({ ok: true });
    await vf.decideQuotation(d, mgr(), (await vf.getJobFlow(d, mgr(), job)).quotations[0].id, "approve");
    const l = await vf.createWorkshopLink(d, mgr(), job, "invoice", { withReply: true });
    await processInboundEmail(d, deps(), { emailId: "staff2", addresses: [replyAddress(l.replyCode!)] });
    expect((await vf.listWorkshopEmails(d, mgr(), job))[0].kind).toBe("invoice");
    await enterForWorkshop(d, mgr(), job, "invoice", { invoice_no: "QF-9", lines: [{ kind: "part", description: "Brake pads", qty: "2", unit_cost: "1500" }] });
    expect(await statusOf(job)).toBe("invoiced");
  });
  it("is refused for people who may not assign, decide or verify, and cannot be used with a text the public form could send", async () => {
    const job = await assigned();
    await expect(enterForWorkshop(d, driver(), job, "quotation", estimate)).rejects.toBeInstanceOf(ForbiddenError);
    const l = await vf.createWorkshopLink(d, mgr(), job, "quotation");
    // the public path drops an injected comment: the history keeps its default line
    expect(await submitViaQuoteLink(d, l.token, { ...estimate, comment: "Approved by the CEO" })).toEqual({ ok: true });
    const ev = await raw(owner(), async (q2) => (await q2.query<{ comment: string | null }>("select comment from job_card_events where job_card_id = $1 and to_status = 'quotation_received'", [job])).rows[0]);
    expect(ev.comment).toBe("Estimate sent by the workshop through a link");
  });
});

describe("the webhook Resend calls", () => {
  const call = (body: string, signed: boolean, over: Record<string, string> = {}) => {
    const ts = String(Math.floor(Date.now() / 1000));
    const headers: Record<string, string> = { "content-type": "application/json", "svix-id": "msg_9", "svix-timestamp": ts, ...over };
    if (signed) headers["svix-signature"] = `v1,${signWebhook(process.env.RESEND_WEBHOOK_SECRET!, "msg_9", ts, body)}`;
    return inboundRoute(new Request("https://x.test/api/inbound/email", { method: "POST", headers, body }) as unknown as NextRequest);
  };
  it("refuses an unsigned or wrongly signed call before reading anything", async () => {
    const body = JSON.stringify({ type: "email.received", data: { email_id: "abc12345", to: [] } });
    expect((await call(body, false)).status).toBe(401);
    expect((await call(body, false, { "svix-signature": "v1,AAAA" })).status).toBe(401);
  });
  it("is not set up without its secret and key, and says so", async () => {
    const k = process.env.RESEND_API_KEY; delete process.env.RESEND_API_KEY;
    expect((await call("{}", true)).status).toBe(500);
    process.env.RESEND_API_KEY = k;
  });
  it("answers 200 for other events and 400 for a body it cannot read, and refuses a body that is too large", async () => {
    expect((await call(JSON.stringify({ type: "email.delivered", data: { email_id: "abc12345" } }), true)).status).toBe(200);
    expect((await call("{not json", true)).status).toBe(400);
    expect((await call(JSON.stringify({ type: "email.received", data: { email_id: "x" } }), true)).status).toBe(400);
    expect((await call("x".repeat(100_001), true)).status).toBe(413);
  });
});
